import json, datetime, re
CFG = json.loads(r"""{
 "now_var": "now",
 "weekend_days": [
  5,
  6
 ],
 "holidays": [
  "2026-10-26",
  "2026-11-11",
  "2026-11-26",
  "2026-12-25",
  "2027-01-01"
 ],
 "products_vars": [
  "products"
 ],
 "product_id_field": "product_id",
 "days_late_field": "days_late",
 "bands": [
  {
   "min": 1,
   "max": 7,
   "deadline_business_days": 12
  },
  {
   "min": 8,
   "max": 45,
   "deadline_business_days": 7
  }
 ],
 "vague_asks_before_deadline": 1,
 "say": {
  "checking": "One moment, let me check that date.",
  "ok": "{day} works, I can record that date.",
  "not_business_day": "{day} is not a business day. The next business day is {next}. Would {next} work for you?",
  "after_deadline": "The latest date I can record is {deadline}. Would {deadline} work for you?",
  "past": "That date has already passed. Which date from today onward works for you?",
  "ask_exact": "Could you tell me the exact day you can pay?",
  "vague_propose_deadline": "Since I do not have an exact day, the latest date I can record is {deadline}. Would {deadline} work for you?",
  "error": "I could not check that date. Could you tell me the exact day again?"
 }
}""")
MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
def spoken(d):
    return DAYS[d.weekday()] + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1]
def isbd(d):
    return d.weekday() not in CFG['weekend_days'] and d.isoformat() not in CFG['holidays']
def add_bd(d, n):
    c = 0
    while c < n:
        d = d + datetime.timedelta(days=1)
        if isbd(d):
            c += 1
    return d
def next_bd(d):
    d = d + datetime.timedelta(days=1)
    while not isbd(d):
        d = d + datetime.timedelta(days=1)
    return d
def load_products():
    for name in CFG['products_vars']:
        v = vars.get(name)
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                try:
                    import ast
                    v = ast.literal_eval(v)
                except Exception:
                    v = None
        if isinstance(v, list) and v:
            return [p for p in v if isinstance(p, dict)]
    found = dict()
    for k in list(vars.keys()):
        m = re.search(r'products\.(\d+)\.(\w+)$', str(k))
        if m:
            found.setdefault(int(m.group(1)), dict())[m.group(2)] = vars.get(k)
    return [found[i] for i in sorted(found.keys())]
decision, say, proposed, pid = 'error', CFG['say']['error'], '', ''
